e GUI --]] -- ============================================================ -- ============================================================ -- PART 1 — INTRO (LUNAHUB) — runs first, then unlocks menu -- ============================================================ -- ============================================================ local introDone = false do local HUB_NAME = "LunaHub" local SUBTITLE = "PREMIUM RIDDLER EXPERIENCE" local ACCENT = Color3.fromRGB(132, 58, 255) local ACCENT_2 = Color3.fromRGB(218, 160, 255) local BACKGROUND = Color3.fromRGB(4, 3, 9) local INTRO_TIME = 5.2 local TAP_TO_SKIP = true local ReplicatedFirst = game:GetService("ReplicatedFirst") local Players = game:GetService("Players") local TweenService = game:GetService("TweenService") local RunService = game:GetService("RunService") ReplicatedFirst:RemoveDefaultLoadingScreen() local player = Players.LocalPlayer or Players.PlayerAdded:Wait() local playerGui = player:WaitForChild("PlayerGui") local old = playerGui:FindFirstChild("ComplexHubIntro") if old then old:Destroy() end local finished = false local closing = false local renderConnection local random = Random.new() local function round(object, radius) local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0, radius) corner.Parent = object return corner end local function outline(object, color, thickness, transparency) local stroke = Instance.new("UIStroke") stroke.Color = color stroke.Thickness = thickness stroke.Transparency = transparency or 0 stroke.Parent = object return stroke end local function addScale(object, value) local scale = Instance.new("UIScale") scale.Scale = value scale.Parent = object return scale end local function play(object, duration, goal, style, direction) if finished or not object or not object.Parent then return end local tween = TweenService:Create( object, TweenInfo.new( duration, style or Enum.EasingStyle.Quint, direction or Enum.EasingDirection.Out ), goal ) tween:Play() return tween end local function waitTime(seconds) local started = os.clock() while not finished and os.clock() - started < seconds do RunService.Heartbeat:Wait() end return not finished end local gui = Instance.new("ScreenGui") gui.Name = "ComplexHubIntro" gui.IgnoreGuiInset = true gui.ResetOnSpawn = false gui.DisplayOrder = 100000 gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling gui.Parent = playerGui local root = Instance.new("Frame") root.Size = UDim2.fromScale(1, 1) root.BackgroundColor3 = BACKGROUND root.BorderSizePixel = 0 root.ClipsDescendants = true root.Parent = gui local backgroundGradient = Instance.new("UIGradient") backgroundGradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(2, 2, 6)), ColorSequenceKeypoint.new(0.45, Color3.fromRGB(17, 7, 31)), ColorSequenceKeypoint.new(1, Color3.fromRGB(2, 2, 6)), }) backgroundGradient.Rotation = 20 backgroundGradient.Parent = root local camera = workspace.CurrentCamera while not camera or camera.ViewportSize.X < 20 do RunService.RenderStepped:Wait() camera = workspace.CurrentCamera end local view = camera.ViewportSize local shortest = math.min(view.X, view.Y) local uiScaleValue = math.clamp(shortest / 720, 0.72, 1.12) local scene = Instance.new("Frame") scene.Size = UDim2.fromScale(1, 1) scene.BackgroundTransparency = 1 scene.Parent = root local topPanel = Instance.new("Frame") topPanel.Size = UDim2.fromScale(1, 0.5) topPanel.BackgroundColor3 = Color3.fromRGB(3, 3, 8) topPanel.BorderSizePixel = 0 topPanel.ZIndex = 500 topPanel.Parent = root local bottomPanel = Instance.new("Frame") bottomPanel.AnchorPoint = Vector2.new(0, 1) bottomPanel.Position = UDim2.fromScale(0, 1) bottomPanel.Size = UDim2.fromScale(1, 0.5) bottomPanel.BackgroundColor3 = Color3.fromRGB(3, 3, 8) bottomPanel.BorderSizePixel = 0 bottomPanel.ZIndex = 500 bottomPanel.Parent = root local topEdge = Instance.new("Frame") topEdge.AnchorPoint = Vector2.new(0, 1) topEdge.Position = UDim2.fromScale(0, 1) topEdge.Size = UDim2.new(1, 0, 0, 2) topEdge.BackgroundColor3 = ACCENT topEdge.BackgroundTransparency = 0.15 topEdge.BorderSizePixel = 0 topEdge.Parent = topPanel local bottomEdge = topEdge:Clone() bottomEdge.AnchorPoint = Vector2.new(0, 0) bottomEdge.Position = UDim2.fromScale(0, 0) bottomEdge.Parent = bottomPanel local grid = Instance.new("Frame") grid.Size = UDim2.fromScale(1, 1) grid.BackgroundTransparency = 1 grid.ZIndex = 1 grid.Parent = scene for i = 0, 18 do local vertical = Instance.new("Frame") vertical.Size = UDim2.new(0, 1, 1, 0) vertical.Position = UDim2.fromScale(i / 18, 0) vertical.BackgroundColor3 = ACCENT vertical.BackgroundTransparency = 0.93 vertical.BorderSizePixel = 0 vertical.Parent = grid end for i = 0, 10 do local horizontal = Instance.new("Frame") horizontal.Size = UDim2.new(1, 0, 0, 1) horizontal.Position = UDim2.fromScale(0, i / 10) horizontal.BackgroundColor3 = ACCENT horizontal.BackgroundTransparency = 0.94 horizontal.BorderSizePixel = 0 horizontal.Parent = grid end local particles = {} for i = 1, 42 do local particle = Instance.new("Frame") local size = random:NextInteger(2, 5) particle.AnchorPoint = Vector2.new(0.5, 0.5) particle.Position = UDim2.fromScale( random:NextNumber(0.03, 0.97), random:NextNumber(0.03, 0.97) ) particle.Size = UDim2.fromOffset(size, size) particle.BackgroundColor3 = i % 5 == 0 and Color3.fromRGB(245, 240, 255) or ACCENT_2 particle.BackgroundTransparency = random:NextNumber(0.45, 0.85) particle.BorderSizePixel = 0 particle.ZIndex = 2 particle.Parent = scene round(particle, 999) particles[i] = { object = particle, speed = random:NextNumber(0.008, 0.024), offset = random:NextNumber(0, math.pi * 2), } end local center = Instance.new("Frame") center.AnchorPoint = Vector2.new(0.5, 0.5) center.Position = UDim2.fromScale(0.5, 0.47) center.Size = UDim2.fromOffset(430, 430) center.BackgroundTransparency = 1 center.ZIndex = 20 center.Parent = scene local centerScale = addScale(center, uiScaleValue * 0.72) local glow = Instance.new("Frame") glow.AnchorPoint = Vector2.new(0.