= Vector2.new(0.5, 0.5) dot.Size = UDim2.fromOffset(i % 3 == 0 and 6 or 4, i % 3 == 0 and 6 or 4) dot.BackgroundColor3 = i % 2 == 0 and ACCENT_2 or Color3.fromRGB(250, 247, 255) dot.BackgroundTransparency = 1 dot.BorderSizePixel = 0 dot.ZIndex = 26 dot.Parent = center round(dot, 999) orbitDots[i] = dot end local scan = Instance.new("Frame") scan.AnchorPoint = Vector2.new(0.5, 0.5) scan.Position = UDim2.fromScale(0.5, 0) scan.Size = UDim2.new(1, 0, 0, 90) scan.BackgroundTransparency = 1 scan.BorderSizePixel = 0 scan.ZIndex = 8 scan.Parent = scene local scanGradient = Instance.new("UIGradient") scanGradient.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.82), NumberSequenceKeypoint.new(1, 1), }) scanGradient.Color = ColorSequence.new(ACCENT) scanGradient.Rotation = 90 scanGradient.Parent = scan local titleHolder = Instance.new("Frame") titleHolder.AnchorPoint = Vector2.new(0.5, 0.5) titleHolder.Position = UDim2.fromScale(0.5, 0.69) titleHolder.Size = UDim2.fromOffset(820, 120) titleHolder.BackgroundTransparency = 1 titleHolder.ZIndex = 50 titleHolder.Parent = scene local titleScale = addScale(titleHolder, uiScaleValue) local title = Instance.new("TextLabel") title.Size = UDim2.fromScale(1, 0.58) title.BackgroundTransparency = 1 title.Text = "" title.TextColor3 = Color3.fromRGB(248, 246, 255) title.Font = Enum.Font.GothamBold title.TextSize = 43 title.TextTransparency = 0 title.TextXAlignment = Enum.TextXAlignment.Center title.TextYAlignment = Enum.TextYAlignment.Center title.ZIndex = 51 title.Parent = titleHolder local titleStroke = outline(title, ACCENT, 1, 0.68) local subtitle = Instance.new("TextLabel") subtitle.AnchorPoint = Vector2.new(0.5, 0) subtitle.Position = UDim2.fromScale(0.5, 0.62) subtitle.Size = UDim2.fromScale(1, 0.25) subtitle.BackgroundTransparency = 1 subtitle.Text = SUBTITLE subtitle.TextColor3 = Color3.fromRGB(169, 150, 196) subtitle.Font = Enum.Font.GothamMedium subtitle.TextSize = 12 subtitle.TextTransparency = 1 subtitle.TextXAlignment = Enum.TextXAlignment.Center subtitle.ZIndex = 51 subtitle.Parent = titleHolder local progressBack = Instance.new("Frame") progressBack.AnchorPoint = Vector2.new(0.5, 0.5) progressBack.Position = UDim2.fromScale(0.5, 0.84) progressBack.Size = UDim2.fromOffset(360, 7) progressBack.BackgroundColor3 = Color3.fromRGB(37, 29, 49) progressBack.BackgroundTransparency = 1 progressBack.BorderSizePixel = 0 progressBack.ClipsDescendants = true progressBack.ZIndex = 52 progressBack.Parent = scene round(progressBack, 999) local progressFill = Instance.new("Frame") progressFill.Size = UDim2.fromScale(0, 1) progressFill.BackgroundColor3 = ACCENT progressFill.BorderSizePixel = 0 progressFill.ZIndex = 53 progressFill.Parent = progressBack round(progressFill, 999) local progressGradient = Instance.new("UIGradient") progressGradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, ACCENT), ColorSequenceKeypoint.new(0.62, ACCENT_2), ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)), }) progressGradient.Parent = progressFill local percent = Instance.new("TextLabel") percent.AnchorPoint = Vector2.new(0.5, 0.5) percent.Position = UDim2.fromScale(0.5, 0.89) percent.Size = UDim2.fromOffset(100, 24) percent.BackgroundTransparency = 1 percent.Text = "0%" percent.TextColor3 = Color3.fromRGB(158, 139, 184) percent.TextTransparency = 1 percent.Font = Enum.Font.GothamMedium percent.TextSize = 11 percent.ZIndex = 52 percent.Parent = scene local status = Instance.new("TextLabel") status.AnchorPoint = Vector2.new(0.5, 0.5) status.Position = UDim2.fromScale(0.5, 0.93) status.Size = UDim2.fromOffset(300, 22) status.BackgroundTransparency = 1 status.Text = "Preparing interface" status.TextColor3 = Color3.fromRGB(132, 116, 154) status.TextTransparency = 1 status.Font = Enum.Font.GothamMedium status.TextSize = 10 status.ZIndex = 52 status.Parent = scene local skipButton = Instance.new("TextButton") skipButton.Size = UDim2.fromScale(1, 1) skipButton.BackgroundTransparency = 1 skipButton.Text = "" skipButton.AutoButtonColor = false skipButton.ZIndex = 1000 skipButton.Parent = root local skipText = Instance.new("TextLabel") skipText.AnchorPoint = Vector2.new(0.5, 1) skipText.Position = UDim2.new(0.5, 0, 1, -22) skipText.Size = UDim2.fromOffset(180, 22) skipText.BackgroundTransparency = 1 skipText.Text = "tap to skip" skipText.TextColor3 = Color3.fromRGB(145, 132, 163) skipText.TextTransparency = TAP_TO_SKIP and 0.28 or 1 skipText.Font = Enum.Font.GothamMedium skipText.TextSize = 11 skipText.ZIndex = 1001 skipText.Parent = root local flash = Instance.new("Frame") flash.Size = UDim2.fromScale(1, 1) flash.BackgroundColor3 = Color3.fromRGB(255, 255, 255) flash.BackgroundTransparency = 1 flash.BorderSizePixel = 0 flash.ZIndex = 900 flash.Parent = root local function closeIntro() if closing then return end closing = true finished = true if renderConnection then renderConnection:Disconnect() end TweenService:Create( flash, TweenInfo.new(0.07, Enum.EasingStyle.Linear), {BackgroundTransparency = 0.12} ):Play() task.wait(0.07) TweenService:Create( topPanel, TweenInfo.new(0.65, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut), {Position = UDim2.fromScale(0, -0.5)} ):Play() TweenService:Create( bottomPanel, TweenInfo.new(0.65, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut), {Position = UDim2.fromScale(0, 1.5)} ):Play() TweenService:Create( flash, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {BackgroundTransparency = 1} ):Play() TweenService:Create( root, TweenInfo.new(0.65, Enum.EasingStyle.Quad), {BackgroundTransparency = 1} ):Play() task.wait(0.68) pcall(function() player:SetAttribute("HubIntroFinished", true) end) gui:Destroy() introDone = true end if TAP_TO_SKIP then skipButton.Activated:Connect(closeIntro) else skipButton.Active = false end renderConnection = RunService.RenderStepped:Connect(function(dt) if finished then return end ring1.Rotation += 24 * dt ring2.Rotation -= 38 * dt backgroundGradient.Rotation += 2 * dt progressGradient.Rotation += 22 * dt local time = os.clock() glow.Size = UDim2.fromOffset( 210 + math.sin(time * 2.5) * 16, 210 + math.sin(time * 2.5) * 16 ) coreGlow.Size = UDim2.fromOffset( 52 + math.sin(time * 4.8) * 7, 52 + math.sin(time * 4.8) * 7 ) for i, dot in ipairs(orbitDots) do local radius = i % 2 == 0 and 88 or 62 local speed = i % 2 == 0 and 0.62 or -0.86 local angle = time * speed + (math.pi * 2 / #orbitDots) * i dot.Position = UDim2.fromOffset( 215 + math.cos(angle) * radius, 215 + math.sin(angle) * radius ) end for i, particleData in ipairs(particles) do local particle = particleData.object local x = particle.Position.X.Scale local y = particle.Position.Y.Scale - particleData.speed * dt if y < -0.03 then y = 1.03 x = random:NextNumber(0.03, 0.97) end particle.Position = UDim2.fromScale( x + math.sin(time + particleData.offset) * 0.00015, y ) end end) task.spawn(function() play( topPanel, 0.7, {Position = UDim2.fromScale(0, -0.5)}, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut ) play( bottomPanel, 0.7, {Position = UDim2.fromScale(0, 1.5)}, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut ) if not waitTime(0.38) then return end play(centerScale, 0.75, {Scale = uiScaleValue}, Enum.EasingStyle.Back) play(ring1Stroke, 0.45, {Transparency = 0.15}) play(ring2Stroke, 0.52, {Transparency = 0.22}) play(ring3, 0.4, {BackgroundTransparency = 0.08}) play(ring3Stroke, 0.45, {Transparency = 0.08}) play(core, 0.38, {BackgroundTransparency = 0}) play(coreGlow, 0.38, {BackgroundTransparency = 0.78}) for i, dot in ipairs(orbitDots) do task.delay(i * 0.045, function() play(dot, 0.24, {BackgroundTransparency = 0.05}) end) end play( scan, 1.1, {Position = UDim2.fromScale(0.5, 1)}, Enum.EasingStyle.Linear ) if not waitTime(0.52) then return end for i = 1, #HUB_NAME do if finished then return end title.Text = string.sub(HUB_NAME, 1, i) if string.sub(HUB_NAME, i, i) ~= " " then play(core, 0.07, {Size = UDim2.fromOffset(23, 23)}) task.delay(0.07, function() play(core, 0.1, {Size = UDim2.fromOffset(18, 18)}) end) end task.wait(0.035) end play(subtitle, 0.32, {TextTransparency = 0}) play(progressBack, 0.3, {BackgroundTransparency = 0.12}) play(percent, 0.3, {TextTransparency = 0}) play(status, 0.3, {TextTransparency = 0}) if not waitTime(0.28) then return end local loadStart = os.clock() local loadDuration = math.max(1.3, INTRO_TIME - 2.4) play( progressFill, loadDuration, {Size = UDim2.fromScale(1, 1)}, Enum.EasingStyle.Quart, Enum.EasingDirection.InOut ) while not finished do local progress = math.clamp((os.clock() - loadStart) / loadDuration, 0, 1) local value = math.floor(progress * 100) percent.Text = value .. "%" if value < 30 then status.Text = "Preparing interface" elseif value < 65 then status.Text = "Loading modules" elseif value < 92 then status.Text = "Finalizing" else status.Text = "Ready" end if progress >= 1 then break end RunService.RenderStepped:Wait() end if finished then return end percent.Text = "100%" status.Text = "Ready" play(flash, 0.06, {BackgroundTransparency = 0.12}, Enum.EasingStyle.Linear) play(centerScale, 0.15, {Scale = uiScaleValue * 1.12}) play(titleScale, 0.15, {Scale = uiScaleValue * 1.04}) if not waitTime(0.07) then return end play(flash, 0.25, {BackgroundTransparency = 1}, Enum.EasingStyle.Quad) play(centerScale, 0.22, {Scale = uiScaleValue}) play(titleScale, 0.22, {Scale = uiScaleValue}) if not waitTime(0.25) then return end topPanel.Position = UDim2.fromScale(0, -0.5) bottomPanel.Position = UDim2.fromScale(0, 1.5) play(topPanel, 0.48, {Position = UDim2.fromScale(0, 0)}) play(bottomPanel, 0.48, {Position = UDim2.fromScale(0, 1)}) if not waitTime(0.45) then return end closeIntro() end) end -- Wait for the intro to finish (safety timeout of 20s in case something stalls) local introWaitStart = os.clock() repeat task.wait(0.05) until introDone or (os.clock() - introWaitStart > 20) -- ============================================================ -- ============================================================ -- PART 2 — RIDDLER (opens after the intro, bottom-center) -- ============================================================ -- ============================================================ local cloneref = cloneref or function(o) return o end local Players = cloneref(game:GetService("Players")) local RS = cloneref(game:GetService("ReplicatedStorage")) local UIS = cloneref(game:GetService("UserInputService")) local TS = cloneref(game:GetService("TweenService")) local HS = cloneref(game:GetService("HttpService")) local CoreGui = cloneref(game:GetService("CoreGui")) local RunService = cloneref(game:GetService("RunService")) local LP = Players.LocalPlayer if not LP then Players:GetPropertyChangedSignal("LocalPlayer"):Wait(); LP = Players.LocalPlayer end local PG = LP:WaitForChild("PlayerGui") local getupvalues = (debug and (debug.getupvalues or debug.getupvalue)) or getupvalues local getconns = getconnections or (debug and debug.getconnections) local httpRequest = (syn and syn.request) or http_request or request or (http and http.request) local env = typeof(getgenv) == "function" and getgenv() or _G if env.StopRiddler then pcall(env.StopRiddler) end -- ============================================================ -- UTILS -- ============================================================ local FR, FM, FB, FBK = Enum.Font.Gotham, Enum.Font.GothamMedium, Enum.Font.GothamBold, Enum.Font.GothamBlack local function new(cls, props, parent) local o = Instance.new(cls) for k, v in pairs(props or {}) do o[k] = v end if parent then o.Parent = parent end return o end local function corner(o, r) return new("UICorner", { CornerRadius = UDim.new(0, r or 6) }, o) end local function stroke(o, col, th, tr) return new("UIStroke", { Color = col or Color3.fromRGB(30,60,120), Thickness = th or 1, Transparency = tr or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, o) end local function gradient(o, c1, c2, rot) return new("UIGradient", { Color = ColorSequence.new(c1,