==================== -- Single-answer path (used when SECURE ANSWER is off). local function localExactAnswer(text) if not text or text == "" then return nil end local l = text:lower() local clean = l clean = clean:gsub("what%s+is", ""):gsub("what%s+are", ""):gsub("what%s+was", ""):gsub("what%s+were", "") clean = clean:gsub("who%s+is", ""):gsub("who%s+was", ""):gsub("when%s+is", ""):gsub("when%s+was", "") clean = clean:gsub("where%s+is", ""):gsub("where%s+are", ""):gsub("how%s+old", ""):gsub("how%s+tall", "") clean = clean:gsub("how%s+many", ""):gsub("how%s+much", ""):gsub("do%s+you%s+know", ""):gsub("can%s+you%s+tell", "") clean = clean:gsub("tell%s+me", ""):gsub("i%s+need", ""):gsub("give%s+me", ""):gsub("what's", ""):gsub("whats", "") clean = clean:gsub("am%s+i", ""):gsub("do%s+i", ""):gsub("did%s+i", ""):gsub("have%s+i", "") clean = clean:gsub("^my%s+", ""):gsub("%s+my%s+", " "):gsub("^sammy[s]?%s+", ""):gsub("^sammys%s+", "") clean = clean:gsub("the%s+", ""):gsub("%f[%a]a%f[%A]", ""):gsub("%f[%a]an%f[%A]", ""):gsub("of%s+", ""):gsub("for%s+", "") clean = clean:gsub("[%?%.%,!]", ""):gsub("^%s+", ""):gsub("%s+$", "") clean = clean:gsub("%d+", ""):gsub("%s+", " ") clean = trim(clean) local raw = trim(l:gsub("[%?%.%,!]", ""):gsub("%s+", " ")) -- Multi-answer lookup returns the FIRST entry if SAB_MULTI[clean] then return SAB_MULTI[clean][1] end if SAB_MULTI[raw] then return SAB_MULTI[raw][1] end if SAB_DB[clean] then return SAB_DB[clean] end if SAB_DB[raw] then return SAB_DB[raw] end local ordinals = {one=1,two=2,three=3,four=4,five=5,six=6,seven=7,eight=8,nine=9,ten=10, eleven=11,twelve=12,thirteen=13,fourteen=14,fifteen=15,sixteen=16,seventeen=17,eighteen=18} local numwords = {first=1,second=2,third=3,fourth=4,fifth=5,sixth=6,seventh=7,eighth=8,ninth=9,tenth=10, eleventh=11,twelfth=12,thirteenth=13,fourteenth=14,fifteenth=15,sixteenth=16,seventeenth=17,eighteenth=18} local suffixes = {[1]="1st",[2]="2nd",[3]="3rd"} local function ord(n) return suffixes[n] or (n.."th") end local conv = clean for word, n in pairs(numwords) do conv = conv:gsub("%f[%a]"..word.."%f[%A]", ord(n)) end for word, n in pairs(ordinals) do conv = conv:gsub("%f[%a]"..word.."%f[%A]", tostring(n)) end if conv ~= clean and SAB_DB[conv] then return SAB_DB[conv] end local kind, num2 = conv:match("^(.-)%s+(%d+)$") if kind and num2 then local alt = ord(tonumber(num2)).." "..trim(kind) if SAB_DB[alt] then return SAB_DB[alt] end end local num3, kind2 = conv:match("^(%d+)%s+(.-)$") if num3 and kind2 then local alt = ord(tonumber(num3)).." "..trim(kind2) if SAB_DB[alt] then return SAB_DB[alt] end end return nil end -- Multi-answer path (used when SECURE ANSWER is on). -- Returns a LIST of candidate answers, in priority order. local function localExactAnswers(text) if not text or text == "" then return nil end local l = text:lower() local clean = l clean = clean:gsub("what%s+is", ""):gsub("what%s+are", ""):gsub("what%s+was", ""):gsub("what%s+were", "") clean = clean:gsub("who%s+is", ""):gsub("who%s+was", ""):gsub("when%s+is", ""):gsub("when%s+was", "") clean = clean:gsub("where%s+is", ""):gsub("where%s+are", ""):gsub("how%s+old", ""):gsub("how%s+tall", "") clean = clean:gsub("how%s+many", ""):gsub("how%s+much", ""):gsub("do%s+you%s+know", ""):gsub("can%s+you%s+tell", "") clean = clean:gsub("tell%s+me", ""):gsub("i%s+need", ""):gsub("give%s+me", ""):gsub("what's", ""):gsub("whats", "") clean = clean:gsub("am%s+i", ""):gsub("do%s+i", ""):gsub("did%s+i", ""):gsub("have%s+i", "") clean = clean:gsub("^my%s+", ""):gsub("%s+my%s+", " "):gsub("^sammy[s]?%s+", ""):gsub("^sammys%s+", "") clean = clean:gsub("the%s+", ""):gsub("%f[%a]a%f[%A]", ""):gsub("%f[%a]an%f[%A]", ""):gsub("of%s+", ""):gsub("for%s+", "") clean = clean:gsub("[%?%.%,!]", ""):gsub("^%s+", ""):gsub("%s+$", "") clean = clean:gsub("%d+", ""):gsub("%s+", " ") clean = trim(clean) local raw = trim(l:gsub("[%?%.%,!]", ""):gsub("%s+", " ")) -- 1) Multi-answer lookup local multi = SAB_MULTI[clean] or SAB_MULTI[raw] if multi then local out = {} for _, v in ipairs(multi) do out[#out + 1] = v end return out end -- 2) Single-answer fallback wrapped in a list local single = localExactAnswer(text) if single then return { single } end return nil end local GROQ_API_KEY = env.GROQ_API_KEY or "AQ.Ab8RN6IBkoyj5cUpARxa9x8oD0Q9kdbJNOgpTdQDwaoul_ajqQ" local AI_SYSTEM = table.concat({ "You are a riddle-answering bot for the Roblox game STEAL A BRAINROT (SAB).", "", "=== CRITICAL OUTPUT RULES ===", "1. Reply with ONE single word in ALL CAPS. NOTHING else.", "2. NEVER include spaces. Write HEADLESSHORSEMAN not HEADLESS HORSEMAN.", "3. NEVER repeat the answer. Return the base answer exactly once.", "4. NEVER spell out numbers as words. Write digits: 24, 2025.", "5. No explanation, just the single answer word.", "", "=== CONTEXT ===", "All personal questions refer to SAMMY (SpyderSammy). No exceptions.", "", "=== OWNER ===", "Real name: SAMMY | Roblox: SPYDERSAMMY", "Age: 24 | Birth year: 2002 | Born day: FRIDAY | Birth month: FEBRUARY", "Country: BRAZIL | State+City: SAOPAULO", "Favorite color: BLUE | Favorite sport: FOOTBALL | Favorite food: PIZZA", "Favorite player: RONALDO | Favorite animal: SPIDER", "YouTube/Twitter/TikTok/Instagram: SPYDERSAMMY", "Favorite number: SEVEN", "", "=== GAME ===", "Full name: STEALABRAINROT | Genre: SIMULATOR", "Release: MAY 16 2025 | Day: FRIDAY | Year: 2025", "Max server size: EIGHT", "First trait: LIGHTNING | Lightning strike trait: MATEO", "Total mutations: THIRTEEN | Total machines: EIGHTEEN | Total rarities: SIX", "", "=== RARITIES ===", "COMMON < UNCOMMON < RARE < EPIC < LEGENDARY < OG", "Rarest brainrot: HEADLESSHORSEMAN | Most popular: SKIBIDITOILET", "", "=== OG BRAINROTS ===", "1st: STRAWBERRYELEPHANT | 2nd: MEOWL | 3rd: SKIBIDITOILET | 5th: JOHNPORK", "", "=== MUTATIONS ===", "1=GOLD 2=DIAMOND 3=BLOODROT 4=RAINBOW 5=CANDY 6=LAVA 7=GALAXY", "8=YINYANG 9=RADIOACTIVE 10=CURSED 11=DIVINE 12=CYBER 13=PHANTOM 14=CRYSTAL", "Evil: CURSED | Angelic: DIVINE", "", "=== MACHINES ===", "1=RAINBOWMACHINE 2=BUBBLEGUMMACHINE 3=FUSEMACHINE 4=CRAFTMACHINE", "5=WITCHFUSE 6=BRAINROTDEALER 7=BRAINROTTRADER 8=SANTASFUSE", "9=SANTASSHOP 10=NEWYEARSMACHINE 11=DUELSMACHINE 12=CUPIDSMACHINE", "13=TRADEMACHINE 14=DIVINEFUSE 15=EGGINCUBATOR 16=CYBERCRAFTMACHINE", "17=SUMMERFUSE 18=LOSTRADERS", }, "\n") local function queryAI(question) if not httpRequest then return nil, "no http executor" end if not GROQ_API_KEY or GROQ_API_KEY == "" then return nil, "GROQ_API_KEY empty" end local body = HS:JSONEncode({ model = "llama-3.3-70b-versatile", messages = { { role = "system", content = AI_SYSTEM }, { role = "user", content = "/no_think\n" .. tostring(question) .. "\n\nRules: ONE word, ALL CAPS, NO spaces, NO repetition, NO spelling out numbers. Just the answer." }, }, temperature = 0, max_tokens = 64, }) local ok, res = pcall(httpRequest, { Url = "https://api.groq.com/openai/v1/chat/completions", Method = "POST", Headers = { ["Content-Type"] = "application/json", ["Authorization"] = "Bearer " .. GROQ_API_KEY }, Body = body, }) if not ok then return nil, "http: " .. tostring(res):sub(1, 100) end if not res or not res.Body then return nil, "empty body" end local sc = tonumber(res.StatusCode) if sc and sc ~= 200 then return nil, "HTTP " .. tostring(sc) end local pOk, parsed = pcall(HS.JSONDecode, HS, res.Body) if not pOk or not parsed then return nil, "json fail" end if parsed.error then return nil, "API: " .. tostring(parsed.error.message):sub(1, 100) end local choice = parsed.choices and parsed.choices[1] if not choice then return nil, "no choices" end local answer = trim((choice.message and choice.message.content) or "") :upper():gsub("[%s%?%.%,!\"'`\n\r]+", "") if answer == "" then return nil, "empty answer" end if answer:find(":") then answer = answer:match(":([^:]+)$") or answer end return answer end local function extractTimesMultiplier(text) local l = text:lower() if l:find("twice") then return 2 end if l:find("thrice") then return 3 end local n = l:match("(%d+)%s*times") if n then n = tonumber(n) if n and n >= 2 and n <= 10 then return n end end return nil end local function stripMultiplierText(text) local s = text s = s:gsub("%s*%d+%s*[Tt]imes%s*", " ") s = s:gsub("%s*[Tt]wice%s*", " ") s = s:gsub("%s*[Tt]hrice%s*", " ") s = trim(s) if s == "" then s = text end return s end local function stripTrailingNumber(text) return trim(text:gsub("%s+%d+%s*$", "")) end local function splitAllParts(text) local clean = text or "" clean = clean:gsub("%s+add%s+", " and ") clean = clean:gsub("%s*,%s*", " and ") clean = clean:gsub("%s+at%s+the%s+end", " ") clean = clean:gsub("%s+at%s+the%s+start", " ") local parts = {} for part in (clean .. " and "):gmatch("(.-)%s+and%s+") do part = trim(part) if part ~= "" then parts[#parts + 1] = part end end if #parts == 0 then parts[1] = trim(text or "") end return parts end -- ============================================================ -- SOLVERS — single & multi -- ============================================================ local solveRiddle local solveRiddleMulti do -- ── single-answer path ── local function resolvePart(part, cb) local multiplier = extractTimesMultiplier(part) local q = stripMultiplierText(part) q = stripTrailingNumber(q) q = q:gsub("%s+at%s+the%s+end%s*$", ""):gsub("%s+at%s+the%s+start%s*$", "") q = trim(q) if q == "" then return nil end local onlyNum = q:match("^%d+$") if onlyNum then return multiplier and string.rep(onlyNum, multiplier) or onlyNum end local a = localExactAnswer(q) if not a then if cb then cb("AI: " .. q:sub(1, 40)) end a = select(1, queryAI(q)) end if not a then return nil end local clean = tostring(a):upper():gsub("%s+", ""):gsub("[%?%.%,!\"'`]", "") if clean:find("ATTHEEND") or clean:find("ATTHESTART") or clean == "AND" then return nil end if clean == "" then return nil end return multiplier and string.rep(clean, multiplier) or clean end solveRiddle = function(text, cb) local suffix = text:match("%s*(%d+)%s*$") or text:match("%s*(%d+)[%.,;!?]%s*$") local parts = splitAllParts(text) local answers = {} for _, part in ipairs(parts) do local ok, result = pcall(resolvePart, part, cb) if ok and result and result ~= "" then answers[#answers + 1] = result end end if #answers == 0 then if cb then cb("AI full question") end local a = select(1, queryAI(stripTrailingNumber(text))) if a then local clean = tostring(a):upper():gsub("%s+", ""):gsub("[%?%.%,!\"'`]", "") clean = clean:gsub("ATTHEEND", ""):gsub("ATTHESTART", "") if suffix and clean:sub(-#suffix) ~= suffix then clean = clean .. suffix end return clean end return nil, "no answer" end local out = table.concat(answers, "") if suffix and out:sub(-#suffix) ~= suffix then out = out .. suffix end return out end -- ── multi-answer path (used when SECURE ANSWER is on) ── local function resolvePartMulti(part, cb) local multiplier = extractTimesMultiplier(part) local q = stripMultiplierText(part) q = stripTrailingNumber(q) q = q:gsub("%s+at%s+the%s+end%s*$", ""):gsub("%s+at%s+the%s+start%s*$", "") q = trim(q) if q == "" then return nil end local onlyNum = q:match("^%d+$") if onlyNum then local v = multiplier and string.rep(onlyNum, multiplier) or onlyNum return { v } end -- try local (single OR multi) local candidates = localExactAnswers(q) if candidates then local out = {} for _, a in ipairs(candidates) do local clean = tostring(a):upper():gsub("%s+", ""):gsub("[%?%.%,!\"'`]", "") if clean ~= "" and not clean:find("ATTHEEND") and not clean:find("ATTHESTART") and clean ~= "AND" then out[#out + 1] = multiplier and string.rep(clean, multiplier) or clean end end if #out > 0 then return out end end -- fall back to AI (single answer) if cb then cb("AI: " .. q:sub(1, 40)) end local a = select(1, queryAI(q)) if not a then return nil end local clean = tostring(a):upper():gsub("%s+", ""):gsub("[%?%.%,!\"'`]", "") if clean == "" or clean:find("ATTHEEND") or clean:find("ATTHESTART") then return nil end return { multiplier and string.rep(clean, multiplier) or clean } end solveRiddleMulti = function(text, cb) local suffix = text:match("%s*(%d+)%s*$") or text:match("%s*(%d+)[%.,;!?]%s*$") local parts = splitAllParts(text) -- collect candidate list per part local partLists = {} for _, part in ipairs(parts) do local ok, result = pcall(resolvePartMulti, part, cb) if ok and result and #result > 0 then partLists[#partLists + 1] = result end end if #partLists == 0 then -- fall back to AI full question (single answer) if cb then cb("AI full question") end local a = select(1, queryAI(stripTrailingNumber(text))) if a then local clean = tostring(a):upper():gsub("%s+", ""):gsub("[%?%.%,!\"'`]", "") clean = clean:gsub("ATTHEEND", ""):gsub("ATTHESTART", "") if suffix and clean:sub(-#suffix) ~= suffix then clean = clean .. suffix end return { clean } end return nil, "no answer" end -- Cartesian product across parts (capped at 12 to prevent explosion) local combos = { "" } for _, list in ipairs(partLists) do local newCombos = {} for _, prefix in ipairs(combos) do for _, ans in ipairs(list) do newCombos[#newCombos + 1] = prefix .. ans end end combos = newCombos if #combos > 12 then local trimmed = {} for i = 1, 12 do trimmed[i] = combos[i] end combos = trimmed end end -- dedupe + apply suffix local seen = {} local out = {} for _, c in ipairs(combos) do if suffix and c:sub(-#suffix) ~= suffix then c = c .. suffix end if not seen[c] then seen[c] = true out[#out + 1] = c end end return out end end -- ============================================================ -- NOTIFY REMOTE RESOLVER -- ============================================================ local function resolveNotifyRemote() if _G.PhiNotifyRemote and typeof(_G.PhiNotifyRemote) == "Instance" then return _G.PhiNotifyRemote end if env.RiddlerNotifyRemote and typeof(env.RiddlerNotifyRemote) == "Instance" then return env.RiddlerNotifyRemote end local ok, controller = pcall(function() local controllers = RS:FindFirstChild("Controllers") local n = controllers and controllers:FindFirstChild("NotificationController", true) if n then return require(n) end end) if ok and type(controller) == "table" and type(controller.Start) == "function" and getupvalues then local vOk, values = pcall(getupvalues, controller.Start) if vOk and type(values) == "table" then for _, v in pairs(values) do if typeof(v) == "Instance" and (v:IsA("RemoteEvent") or v:IsA("RemoteFunction") or v:IsA("UnreliableRemoteEvent")) then return v end end end end local pkg = RS:FindFirstChild("Packages") if pkg and getconns and debug then local getinfo = debug.getinfo or debug.info local containers = {} local netA = pkg:FindFirstChild("Net") if netA then table.insert(containers, netA) end local netB = pkg:FindFirstChild("Network") if netB then table.insert(containers, netB) end for _, net in ipairs(containers) do for _, d in ipairs(net:GetDescendants()) do if d:IsA("RemoteEvent") or d:IsA("UnreliableRemoteEvent") then local cOk, cs = pcall(getconns, d.OnClientEvent) if cOk and type(cs) == "table" then for _, c in ipairs(cs) do local f, fn = pcall(function() return c.Function end) if f and type(fn) == "function" then local i, info = pcall(getinfo, fn) local src = i and tostring(info.short_src or info.source or "") or "" if src:find("NotificationController", 1, true) then return d end end end end end end end end end -- ============================================================ -- STATE -- ============================================================ local state = { enabled = false, listening = false, autoRedeem = true, secureAnswer = true, -- try ALL candidate answers when a riddle has more than one autoCopy = true, openFeedOnHit = true, autoListen = true, ignoreSystem = true, duoCount = 0, uiScale = "TINY", model = "FAST", palette = "BLUE", } -- ============================================================ -- ROOT GUI -- ============================================================ local old = PG:FindFirstChild("RiddlerUI"); if old then old:Destroy() end local SG = new("ScreenGui", { Name = "RiddlerUI", Res